update public.cms_sections set data='{"eyebrow": "Ready when required", "heading": "Road Transport Fleet & Equipment in Pakistan", "description": "An assured fleet network and our tanker fleet, with the right vehicle matched to your cargo and ready exactly when required.", "action": {"label": "Discuss Your Requirement", "path": "/contact-us"}, "image": "/fleet-and-visiblity/fleet-and-equipment/section-1-main-image.png", "imageAlt": "LMI tankers, trucks and flatbed lined up", "imagePlaceholder": "[Photo: LMI tankers, trucks and flatbed lined up]"}'::jsonb,revision=70 where page_id='fleet-visibility--fleet-equipment' and key='sectionOne';
