update public.cms_sections set data='{"eyebrow": "Our network", "heading": "Locations We Connect", "description": "From Karachi, we connect the places where cargo is made, stored, processed and used.", "locations": [{"heading": "Ports & Terminals", "description": "Cargo lifted from Karachi’s ports and terminals.", "image": "/fleet-and-visiblity/nationwide-network/section-4-image-1.png", "imageAlt": "Ports & Terminals", "imagePlaceholder": "[Photo: Ports & Terminals]"}, {"heading": "Refineries & Industrial Plants", "description": "Petroleum, chemical and manufacturing sites.", "image": "/fleet-and-visiblity/nationwide-network/section-4-image-2.png", "imageAlt": "Refineries & Industrial Plants", "imagePlaceholder": "[Photo: Refineries & Industrial Plants]"}, {"heading": "Warehouses & Distribution Points", "description": "Movements between storage and customers.", "image": "/fleet-and-visiblity/nationwide-network/section-4-image-3.png", "imageAlt": "Warehouses & Distribution Points", "imagePlaceholder": "[Photo: Warehouses & Distribution Points]"}, {"heading": "Construction & Project Sites", "description": "Machinery and materials to remote sites.", "image": "/fleet-and-visiblity/nationwide-network/section-4-image-4.png", "imageAlt": "Construction & Project Sites", "imagePlaceholder": "[Photo: Construction & Project Sites]"}, {"heading": "Customer Locations", "description": "Commercial and industrial delivery points nationwide.", "image": "/fleet-and-visiblity/nationwide-network/section-4-image-5.png", "imageAlt": "Customer Locations", "imagePlaceholder": "[Photo: Customer Locations]"}]}'::jsonb,revision=70 where page_id='fleet-visibility--nationwide-network' and key='sectionFour';
update public.cms_sections set data='{"eyebrow": "Coverage", "heading": "Nationwide Road Transportation From Karachi", "description": "LMI moves cargo from Karachi’s ports, plants and terminals to destinations across Pakistan, with a suitable vehicle ready exactly when required.", "action": {"label": "Discuss Your Requirement", "path": "/contact-us"}, "image": "/fleet-and-visiblity/nationwide-network/section-1-main-image.png", "imageAlt": "LMI truck on a highway", "imagePlaceholder": "[Photo: LMI truck on a highway]"}'::jsonb,revision=70 where page_id='fleet-visibility--nationwide-network' and key='sectionOne';
update public.cms_sections set data='{"eyebrow": "Stay informed", "heading": "Shipment Tracking & Operational Visibility in Pakistan", "description": "Stay informed from dispatch to delivery, so your team and the receiving site know where the cargo is and when it arrives.", "action": {"label": "Discuss Your Requirement", "path": "/contact-us"}, "image": "/fleet-and-visiblity/shipment-tracking-and-visibility/section-1-main-image.png", "imageAlt": "LMI operations desk monitoring vehicles", "imagePlaceholder": "[Photo: LMI operations desk monitoring vehicles]"}'::jsonb,revision=70 where page_id='fleet-visibility--shipment-tracking-operational-visibility' and key='sectionOne';
update public.cms_sections set data='{"eyebrow": "Visibility in practice", "heading": "More Than a Map Pin", "benefits": ["Receiving sites prepare before the cargo arrives", "Customer teams are informed in time", "Route awareness helps plan around delays", "Project teams stay aligned with incoming cargo", "Distribution and onward movements are planned with confidence"], "panelHeading": "Shipment in transit", "status": "In transit", "mapPlaceholder": "[Map: route and vehicle position]", "details": [{"label": "Shipment", "value": "[Shipment ID]"}, {"label": "Route", "value": "[Origin] → [Destination]"}, {"label": "Last update", "value": "[Time and location]"}, {"label": "Expected arrival", "value": "[Date and time]"}], "note": "[Illustrative layout only. Replace with the real tracking view LMI offers.]", "image": "/fleet-and-visiblity/shipment-tracking-and-visibility/section-3-main-image.png", "imageAlt": "Illustrative shipment route and vehicle position"}'::jsonb,revision=70 where page_id='fleet-visibility--shipment-tracking-operational-visibility' and key='sectionThree';
